import { chromium } from 'playwright';
const sets = [
  ['--no-sandbox','--disable-gpu','--disable-dev-shm-usage'],
  ['--no-sandbox','--disable-gpu','--single-process','--no-zygote'],
  ['--no-sandbox','--disable-gpu','--disable-features=NetworkService','--no-zygote','--single-process'],
];
for (const args of sets) {
  try {
    const b = await chromium.launch({ args, timeout: 30000 });
    const p = await b.newPage();
    await p.goto('http://localhost:5180/', { timeout: 30000, waitUntil: 'domcontentloaded' });
    console.log('OK', args.join(' '), await p.title());
    await b.close();
  } catch (e) { console.log('FAIL', args.join(' '), '::', e.message.split('\n')[0]); }
}
EOF
